using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoastalTerrainAudit{
static CoastalTerrainAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("CoastalTerrainAudit.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("CoastalTerrainAudit.request");var log=new StringBuilder();try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!s.isLoaded)throw new Exception("Scene not loaded");foreach(var root in s.GetRootGameObjects()){log.AppendLine("ROOT "+root.name);foreach(var t in root.GetComponentsInChildren<Terrain>(true))log.AppendLine("TERRAIN "+t.name+" position="+t.transform.position+" size="+t.terrainData.size+" resolution="+t.terrainData.heightmapResolution);foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){if(!r.sharedMaterial)continue;var b=r.bounds;string m=r.sharedMaterial.name;if((b.size.x>180||b.size.z>180)&&b.size.y<100||m.ToLower().Contains("terrain")||m.ToLower().Contains("water"))log.AppendLine("SURFACE "+r.name+" material="+m+" center="+b.center+" size="+b.size);}}var road=s.GetRootGameObjects().Single(g=>g.name=="Track Roads");foreach(var r in road.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.sharedMaterial&&r.sharedMaterial.name=="Road Atlas"))log.AppendLine("ROAD "+r.name+" center="+r.bounds.center+" size="+r.bounds.size);}catch(Exception e){log.AppendLine("FAILED "+e);}File.WriteAllText("FinalEnvironmentRoadReview/CoastalTerrainAudit.txt",log.ToString());}}
